/* AIVIC_FUNCTION_BUNDLE_START owner=extractUsageFrequencyAndDropoffPoints exports=extractUsageFrequencyAndDropoffPoints */
const __aivicBundle_18_extractUsageFrequencyAndDropoffPoints = (() => {
  function extractUsageFrequencyAndDropoffPoints(incompleteLogRecords: any[]): { [key: string]: any } {
    // Validate that all records have dropoff_point defined and not null/undefined
    for (const record of incompleteLogRecords) {
      if (record.dropoff_point === null || record.dropoff_point === undefined) {
        throw new Error("離脱ポイント情報が欠損しています");
      }
    }
  
    // Calculate usage frequency by feature
    const featureUsageMap: { [key: string]: number } = {};
    const featureDropoffMap: { [key: string]: { [key: string]: number } } = {};
    const userFeatureMap: { [key: string]: Set<string> } = {};
  
    for (const record of incompleteLogRecords) {
      const featureName = record.feature_name || "unknown";
      const dropoffPoint = record.dropoff_point;
      const userId = record.user_id;
  
      // Count feature usage
      featureUsageMap[featureName] = (featureUsageMap[featureName] || 0) + 1;
  
      // Track unique users per feature
      if (!userFeatureMap[featureName]) {
        userFeatureMap[featureName] = new Set();
      }
      userFeatureMap[featureName].add(userId);
  
      // Count dropoff points per feature
      if (!featureDropoffMap[featureName]) {
        featureDropoffMap[featureName] = {};
      }
      featureDropoffMap[featureName][dropoffPoint] =
        (featureDropoffMap[featureName][dropoffPoint] || 0) + 1;
    }
  
    // Build dropoff points array with distribution
    const dropoffPoints: Array<{
      feature_name: string;
      dropoff_point: string;
      frequency: number;
      userCount: number;
    }> = [];
  
    for (const [featureName, dropoffCounts] of Object.entries(featureDropoffMap)) {
      for (const [dropoffPoint, count] of Object.entries(dropoffCounts)) {
        dropoffPoints.push({
          feature_name: featureName,
          dropoff_point: dropoffPoint,
          frequency: count as number,
          userCount: userFeatureMap[featureName].size,
        });
      }
    }
  
    // Build usage frequency array
    const usageFrequency: Array<{
      feature_name: string;
      usage_count: number;
      unique_user_count: number;
    }> = [];
  
    for (const [featureName, count] of Object.entries(featureUsageMap)) {
      usageFrequency.push({
        feature_name: featureName,
        usage_count: count as number,
        unique_user_count: userFeatureMap[featureName].size,
      });
    }
  
    return {
      usage_frequency: usageFrequency,
      dropoff_points: dropoffPoints,
      total_records_processed: incompleteLogRecords.length,
      extraction_timestamp: new Date().toISOString(),
    };
  }
  return { extractUsageFrequencyAndDropoffPoints };
})();
export const extractUsageFrequencyAndDropoffPoints = __aivicBundle_18_extractUsageFrequencyAndDropoffPoints.extractUsageFrequencyAndDropoffPoints;
/* AIVIC_FUNCTION_BUNDLE_END owner=extractUsageFrequencyAndDropoffPoints */

/* AIVIC_FUNCTION_BUNDLE_START owner=extractAbandonmentPoints exports=extractAbandonmentPoints */
const __aivicBundle_19_extractAbandonmentPoints = (() => {
  function extractAbandonmentPoints(
    flowLogsInput: Array<{
      userId: string;
      featureName: string;
      flowStep: number;
      stepDescription: string;
      timestamp: string;
      abandonedAt: string;
      isAbandoned: boolean;
    }>
  ): AbandonmentExtractionResult {
    // フロー段階ごとに離脱情報を集計
    const abandonmentByStep = new Map<
      number,
      {
        stepDescription: string;
        abandonmentUserIds: string[];
        abandonmentCount: number;
      }
    >();
  
    // isAbandoned === true のレコードのみを処理
    const abandonedLogs = flowLogsInput.filter((log) => log.isAbandoned === true);
  
    for (const log of abandonedLogs) {
      const key = log.flowStep;
  
      if (!abandonmentByStep.has(key)) {
        abandonmentByStep.set(key, {
          stepDescription: log.stepDescription,
          abandonmentUserIds: [],
          abandonmentCount: 0,
        });
      }
  
      const entry = abandonmentByStep.get(key)!;
      entry.abandonmentUserIds.push(log.userId);
      entry.abandonmentCount += 1;
    }
  
    // 離脱ポイントの配列を構築
    const abandonmentPoints: AbandonmentPoint[] = Array.from(
      abandonmentByStep.entries()
    ).map(([flowStep, data]) => {
      const abandonmentRate =
        abandonedLogs.length > 0 ? data.abandonmentCount / abandonedLogs.length : 0;
  
      return {
        flowStep,
        stepDescription: data.stepDescription,
        abandonmentCount: data.abandonmentCount,
        abandonmentUserIds: data.abandonmentUserIds,
        abandonmentRate,
      };
    });
  
    // 発生頻度（abandonmentCount）でソート（降順）
    abandonmentPoints.sort(
      (a, b) => b.abandonmentCount - a.abandonmentCount
    );
  
    // 全体の離脱ユーザー数
    const totalAbandonmentCount = abandonedLogs.length;
  
    return {
      abandonmentPoints,
      totalAbandonmentCount,
    };
  }
  return { extractAbandonmentPoints };
})();
export const extractAbandonmentPoints = __aivicBundle_19_extractAbandonmentPoints.extractAbandonmentPoints;
/* AIVIC_FUNCTION_BUNDLE_END owner=extractAbandonmentPoints */

/* AIVIC_FUNCTION_BUNDLE_START owner=classifyRejectionReason exports=classifyRejectionReason */
const __aivicBundle_20_classifyRejectionReason = (() => {
  function classifyRejectionReason(reasonText: string): RejectionClassificationResult {
    const normalizedText = reasonText.toLowerCase();
  
    const budgetKeywords = ['予算', '費用', '高い', 'お金', '超過', '超える'];
    const techKeywords = ['時間', '制限', '複雑', '手間', '調理'];
    const priorityKeywords = ['優先', 'したい'];
  
    let budgetScore = 0;
    let techScore = 0;
    let priorityScore = 0;
  
    for (const keyword of budgetKeywords) {
      if (normalizedText.includes(keyword)) {
        budgetScore += 25;
      }
    }
  
    for (const keyword of techKeywords) {
      if (normalizedText.includes(keyword)) {
        techScore += 25;
      }
    }
  
    for (const keyword of priorityKeywords) {
      if (normalizedText.includes(keyword)) {
        priorityScore += 25;
      }
    }
  
    budgetScore = Math.min(budgetScore, 100);
    techScore = Math.min(techScore, 100);
    priorityScore = Math.min(priorityScore, 100);
  
    let category = 'その他';
    let confidence = 0;
  
    if (budgetScore > 0 || techScore > 0 || priorityScore > 0) {
      if (budgetScore >= techScore && budgetScore >= priorityScore) {
        category = '予算不足';
        confidence = budgetScore;
      } else if (techScore >= budgetScore && techScore >= priorityScore) {
        category = '技術的課題';
        confidence = techScore;
      } else if (priorityScore > 0) {
        category = '優先度低';
        confidence = priorityScore;
      }
    } else {
      confidence = 0;
    }
  
    return {
      category,
      confidence,
    };
  }
  return { classifyRejectionReason };
})();
export const classifyRejectionReason = __aivicBundle_20_classifyRejectionReason.classifyRejectionReason;
