const __aivicBundle_22_classifyRejectionReasons = (() => {
  function classifyRejectionReasons(input: {
    menuId: string;
    reasonText: string | null | undefined;
  }): {
    isIncomplete: boolean;
    category: string;
    shouldExcludeFromDifferentiationAnalysis: boolean;
  } {
    // Validate required input: menuId must be present and non-empty
    if (!input.menuId || String(input.menuId).trim() === '') {
      throw new Error('menuId is required');
    }
  
    const reasonText = input.reasonText;
  
    // Check if reasonText is empty, null, or undefined
    const isEmptyOrNull =
      reasonText === '' ||
      reasonText === null ||
      reasonText === undefined;
  
    if (isEmptyOrNull) {
      return {
        isIncomplete: true,
        category: 'INCOMPLETE_DATA',
        shouldExcludeFromDifferentiationAnalysis: true,
      };
    }
  
    // Process valid reason text
    const trimmedReason = String(reasonText).trim();
  
    let category = 'OTHER';
  
    // Classify based on reason keywords
    if (
      trimmedReason.includes('調理時間') ||
      trimmedReason.includes('時間が長') ||
      trimmedReason.includes('調理が長')
    ) {
      category = 'COOKING_TIME';
    } else if (
      trimmedReason.includes('材料') ||
      trimmedReason.includes('食材') ||
      trimmedReason.includes('アレルギー')
    ) {
      category = 'INGREDIENT';
    } else if (
      trimmedReason.includes('味') ||
      trimmedReason.includes('好み') ||
      trimmedReason.includes('好きではない')
    ) {
      category = 'TASTE_PREFERENCE';
    } else if (
      trimmedReason.includes('栄養') ||
      trimmedReason.includes('カロリー') ||
      trimmedReason.includes('健康')
    ) {
      category = 'NUTRITION';
    } else if (
      trimmedReason.includes('難しい') ||
      trimmedReason.includes('手間') ||
      trimmedReason.includes('複雑')
    ) {
      category = 'DIFFICULTY';
    }
  
    return {
      isIncomplete: false,
      category: category,
      shouldExcludeFromDifferentiationAnalysis: false,
    };
  }
  return { classifyRejectionReasons };
})();
