const __aivicBundle_23_detectDiscrepancyBetweenInterviewAndLog = (() => {
  function detectDiscrepancyBetweenInterviewAndLog(input: {
    interview_records: any[];
    log_data: any[];
    matching_key: string;
  }): DiscrepancyDetectionResult {
    const { interview_records, log_data, matching_key } = input;
  
    const discrepancies: DiscrepancyRecord[] = [];
  
    // Group interview records by matching key
    const interviewByKey = new Map<string, any[]>();
    for (const record of interview_records) {
      const key = record[matching_key];
      if (!interviewByKey.has(key)) {
        interviewByKey.set(key, []);
      }
      interviewByKey.get(key)!.push(record);
    }
  
    // Group log data by matching key
    const logByKey = new Map<string, any[]>();
    for (const record of log_data) {
      const key = record[matching_key];
      if (!logByKey.has(key)) {
        logByKey.set(key, []);
      }
      logByKey.get(key)!.push(record);
    }
  
    // Compare frequencies for each matching key
    for (const [keyValue, interviewRecords] of interviewByKey.entries()) {
      const logRecords = logByKey.get(keyValue);
  
      if (logRecords && logRecords.length > 0) {
        // Calculate total frequency counts
        const interviewFrequencyCount = interviewRecords.reduce(
          (sum, rec) => sum + (rec.frequency_count || 0),
          0
        );
        const logFrequencyCount = logRecords.reduce(
          (sum, rec) => sum + (rec.event_count || 0),
          0
        );
  
        // Calculate discrepancy magnitude
        const maxFrequency = Math.max(interviewFrequencyCount, logFrequencyCount);
        const discrepancyMagnitude =
          maxFrequency > 0
            ? (Math.abs(interviewFrequencyCount - logFrequencyCount) / maxFrequency) * 100
            : 0;
  
        // Determine if discrepancy exists (threshold: > 10%)
        const hasDiscrepancy = discrepancyMagnitude > 10;
  
        // Calculate trustworthiness score (inverse of discrepancy magnitude)
        const trustworthinessScore = Math.max(0, 100 - discrepancyMagnitude);
  
        // Build discrepancy record
        const discrepancyRecord: DiscrepancyRecord = {
          pain_factor: keyValue,
          interview_frequency_count: interviewFrequencyCount,
          log_frequency_count: logFrequencyCount,
          discrepancy_magnitude: discrepancyMagnitude,
          discrepancy_flag: hasDiscrepancy,
          interview_record_id: interviewRecords[0]?.interview_id || '',
          log_record_id: logRecords[0]?.log_id || '',
          interview_observation_period: interviewRecords[0]?.interview_date || '',
          log_observation_period: {
            start: logRecords[0]?.observation_period_start || '',
            end: logRecords[0]?.observation_period_end || ''
          },
          trustworthiness_score: trustworthinessScore
        };
  
        discrepancies.push(discrepancyRecord);
      }
    }
  
    // Determine if any discrepancy was detected
    const hasDiscrepancy = discrepancies.some((d) => d.discrepancy_flag);
  
    return {
      has_discrepancy: hasDiscrepancy,
      discrepancies
    };
  }
  return { detectDiscrepancyBetweenInterviewAndLog };
})();
