/* AIVIC_FUNCTION_BUNDLE_START owner=detectDataInconsistency exports=detectDataInconsistency */
const __aivicBundle_25_detectDataInconsistency = (() => {
  function detectDataInconsistency(params: {
    interview_records: any;
    log_data: any;
  }): {
    has_inconsistency: boolean;
    inconsistency_details: Array<{
      type: string;
      interview_user_id?: string;
      log_user_id?: string;
      severity: string;
      interview_date?: string;
      last_log_date?: string;
      gap_days?: number;
    }>;
    confidence_score: number;
    data_quality_status: 'valid' | 'warning' | 'caution';
  } {
    const { interview_records, log_data } = params;
  
    // Validation: null/empty checks
    if (
      interview_records === null ||
      interview_records === undefined ||
      (typeof interview_records === 'object' && Object.keys(interview_records).length === 0)
    ) {
      throw new Error('インタビュー記録が無効です');
    }
  
    if (
      log_data === null ||
      log_data === undefined ||
      !Array.isArray(log_data) ||
      log_data.length === 0
    ) {
      throw new Error('ログデータが無効です');
    }
  
    const inconsistency_details: Array<{
      type: string;
      interview_user_id?: string;
      log_user_id?: string;
      severity: string;
      interview_date?: string;
      last_log_date?: string;
      gap_days?: number;
    }> = [];
  
    const interview_user_id = interview_records.user_id;
    const interview_date = interview_records.interview_date;
  
    // Extract log user_id and latest timestamp
    const log_user_ids = new Set(log_data.map((log: any) => log.user_id));
    const log_timestamps = log_data.map((log: any) => log.timestamp).filter(Boolean);
    const last_log_date = log_timestamps.length > 0
      ? log_timestamps.sort().reverse()[0]
      : null;
  
    // Check 1: User ID mismatch
    if (log_user_ids.size > 0 && !log_user_ids.has(interview_user_id)) {
      const log_user_id = Array.from(log_user_ids)[0] as string;
      inconsistency_details.push({
        type: 'user_id_mismatch',
        interview_user_id,
        log_user_id,
        severity: 'high'
      });
    }
  
    // Check 2: Date gap exceeds threshold (45 days)
    if (interview_date && last_log_date) {
      const interview_date_obj = new Date(interview_date);
      const last_log_date_obj = new Date(last_log_date);
      const gap_ms = Math.abs(last_log_date_obj.getTime() - interview_date_obj.getTime());
      const gap_days = Math.ceil(gap_ms / (1000 * 60 * 60 * 24));
  
      if (gap_days > 30) {
        inconsistency_details.push({
          type: 'date_gap_exceeds_threshold',
          interview_date,
          last_log_date: last_log_date.split('T')[0],
          gap_days,
          severity: 'medium'
        });
      }
    }
  
    // Determine result
    const has_inconsistency = inconsistency_details.length > 0;
  
    let confidence_score = 0.95;
    let data_quality_status: 'valid' | 'warning' | 'caution' = 'valid';
  
    if (has_inconsistency) {
      const has_high_severity = inconsistency_details.some(d => d.severity === 'high');
      const has_medium_severity = inconsistency_details.some(d => d.severity === 'medium');
  
      if (has_high_severity) {
        confidence_score = 0.45;
        data_quality_status = 'warning';
      } else if (has_medium_severity) {
        confidence_score = 0.60;
        data_quality_status = 'caution';
      }
    }
  
    return {
      has_inconsistency,
      inconsistency_details,
      confidence_score,
      data_quality_status
    };
  }
  return { detectDataInconsistency };
})();
export const detectDataInconsistency = __aivicBundle_25_detectDataInconsistency.detectDataInconsistency;
/* AIVIC_FUNCTION_BUNDLE_END owner=detectDataInconsistency */

