const __aivicBundle_28_evaluateDataTrustLevel = (() => {
  function evaluateDataTrustLevel(dataset: {
    interview_records: Array<any>;
    app_logs: Array<any>;
    contradictions: Array<{ type: string; severity: string }>;
  }): number {
    // Validate required inputs are present and usable
    if (
      !dataset.interview_records ||
      !Array.isArray(dataset.interview_records) ||
      dataset.interview_records.length === 0
    ) {
      throw new Error("interview_records is required and must be a non-empty array");
    }
  
    if (
      !dataset.app_logs ||
      !Array.isArray(dataset.app_logs) ||
      dataset.app_logs.length === 0
    ) {
      throw new Error("app_logs is required and must be a non-empty array");
    }
  
    // Extract contradiction count from the contradictions array
    const contradictionCount =
      dataset.contradictions && Array.isArray(dataset.contradictions)
        ? dataset.contradictions.length
        : 0;
  
    // Linear degradation formula:
    // Base score: 100
    // Degradation: 5 points per contradiction
    // Floor: 0 (no negative scores)
    // 0 contradictions → 100
    // 5 contradictions → 75
    // 10 contradictions → 50
    // 15 contradictions → 25
    // 20+ contradictions → 0
    const trustScore = Math.max(0, 100 - contradictionCount * 5);
  
    return trustScore;
  }
  return { evaluateDataTrustLevel };
})();
