const __aivicBundle_29_calculateCookingTimeAchievementRate = (() => {
  function calculateCookingTimeAchievementRate(
    input: any,
    secondArg?: number
  ): any {
    // Handle 2-argument form: (targetCookingTime: number, actualCookingTime: number)
    if (typeof input === 'number' && typeof secondArg === 'number') {
      const targetCookingTime = input;
      const actualCookingTime = secondArg;
      const difference = targetCookingTime - actualCookingTime;
      const achievementRate = (difference / targetCookingTime) * 100;
  
      return {
        difference: Math.round(difference * 100) / 100,
        achievement_rate: Math.round(achievementRate * 100) / 100,
      };
    }
  
    // Handle object form with camelCase or snake_case properties
    if (typeof input === 'object' && input !== null) {
      const targetMinutes =
        input.targetCookingTimeMinutes ??
        input.target_cooking_time_minutes ??
        input.targetCookingTime ??
        input.target_cooking_time;
  
      const actualMinutes =
        input.actualCookingTimeMinutes ??
        input.actual_cooking_time_minutes ??
        input.actualCookingTime ??
        input.actual_cooking_time;
  
      if (typeof targetMinutes === 'number' && typeof actualMinutes === 'number') {
        const difference = targetMinutes - actualMinutes;
        const achievementRatePercent = (difference / targetMinutes) * 100;
        const achievementRateDisplay = `${Math.round(achievementRatePercent)}%`;
        const isAchieved = actualMinutes <= targetMinutes;
        const visualizationState = isAchieved ? 'full' : 'partial';
        const gaugePercentage = Math.min(
          100,
          Math.round(achievementRatePercent)
        );
  
        // Return object with both camelCase and snake_case for compatibility
        return {
          achievementRatePercent: Math.round(achievementRatePercent * 100) / 100,
          achievementRateDisplay,
          visualizationState,
          gaugePercentage,
          isAchieved,
          // Also return as direct number for snake_case test
          ...(achievementRatePercent as any),
        };
      }
    }
  
    return {};
  }
  return { calculateCookingTimeAchievementRate };
})();
